153	// ---- users and members
154	
155	// CreateUser adds a user. Email addresses are unique, ignoring case.
156	func (s *Store) CreateUser(email, name string, now time.Time) (User, error) {
157		email, name = strings.TrimSpace(email), strings.TrimSpace(name)
158		if !validEmail(email) {
159			return User{}, invalid("a user needs a valid email address")
160		}
161		if name == "" {
162			return User{}, invalid("a user needs a name")
163		}
164		s.mu.Lock()
165		defer s.mu.Unlock()
166		if _, ok := s.usersByEmail[normEmail(email)]; ok {
167			return User{}, ErrEmailTaken
168		}
169		u := User{ID: s.newID("usr"), Email: email, Name: name, CreatedAt: now.UTC()}
170		s.users[u.ID] = u
171		s.usersByEmail[normEmail(email)] = u.ID
172		return u, nil
173	}
174	
175	// User returns a user.
176	func (s *Store) User(id string) (User, bool) {
177		s.mu.Lock()
178		defer s.mu.Unlock()
179		u, ok := s.users[id]
180		return u, ok
181	}
182	
183	// UserByEmail finds a user by email address, ignoring case.
184	func (s *Store) UserByEmail(email string) (User, bool) {
185		s.mu.Lock()
186		defer s.mu.Unlock()
187		id, ok := s.usersByEmail[normEmail(email)]
188		if !ok {
189			return User{}, false
190		}
191		return s.users[id], true
192	}
