14	func TestCreateChargesTheFirstPeriod(t *testing.T) {
15		e := apitest.New(t)
16		ctx := context.Background()
17		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
18		_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
19		p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
20		sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 3})
21		if err != nil {
22			t.Fatal(err)
23		}
24		now := e.Clock.Now()
25		if sub.Status != store.Active || !sub.CurrentPeriodStart.Equal(now) || !sub.CurrentPeriodEnd.Equal(now.AddDate(0, 1, 0)) {
26			t.Fatalf("subscription = %+v", sub)
27		}
28		invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
29		if len(invs) != 1 || invs[0].Status != store.InvoicePaid || invs[0].Lines[0].Quantity != 3 || invs[0].Lines[0].UnitAmount != 2000 {
30			t.Fatalf("invoices = %+v", invs)
31		}
32		if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 6000 {
33			t.Fatalf("charges = %+v", cs)
34		}
35	}
