48	func TestTrialThenRenewal(t *testing.T) {
49		e := apitest.New(t)
50		ctx := context.Background()
51		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
52		p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 4900, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
53		if err != nil {
54			t.Fatal(err)
55		}
56		sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
57		if err != nil {
58			t.Fatal(err)
59		}
60		trialEnd := e.Clock.Now().AddDate(0, 0, 14)
61		if sub.Status != store.Trialing || sub.TrialEnd == nil || !sub.TrialEnd.Equal(trialEnd) || !sub.CurrentPeriodEnd.Equal(trialEnd) {
62			t.Fatalf("subscription = %+v", sub)
63		}
64		if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
65			t.Fatalf("a trial was invoiced: %+v", invs)
