236	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
237	// It reports false when the charge was declined, and an error when the gateway failed; then the invoice stays open. A period
238	// that already has an invoice is not invoiced or charged again. An invoice that needs no charge is marked paid; one whose
239	// customer has no payment method stays open and counts as paid here (it is paid by hand).
240	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
241		var lines []store.Line
242		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
243		switch plan.UsageType {
244		case store.Licensed:
245			if plan.UnitAmount > 0 {
246				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
247			}
248		case store.Metered:
249			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
250				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
